
#[cfg(test)]mod fin1_loan_tests{
 use super::*;use crate::circuit::{Op,OperationType,analyze_ops};use crate::sim::Simulator;use sha3::{Shake256,digest::{Update,ExtendableOutput,XofReader}};
 thread_local!{static ON:std::cell::Cell<bool>=const{std::cell::Cell::new(false)};static SNAP:std::cell::RefCell<Option<Vec<QubitId>>>=const{std::cell::RefCell::new(None)};}
 pub(super)fn capture(c1:QubitId,c3:QubitId,c4:QubitId,c5:QubitId,c6:QubitId,recs:&[Rec])->bool{if !ON.with(|x|x.get()){return false;}let mut held=vec![c1,c3,c4];for r in recs{held.push(match r{Rec::And(q,..)|Rec::Maj(q,..)=>*q,Rec::UndoC5=>c5,Rec::UndoC6=>c6});}assert_eq!(held.len(),30);SNAP.with(|x|*x.borrow_mut()=Some(held));true}
 include!("fin1_certificate.rs");
 struct Words{bytes:Vec<u8>,pos:usize}impl XofReader for Words{fn read(&mut self,b:&mut[u8]){b.copy_from_slice(&self.bytes[self.pos..self.pos+b.len()]);self.pos+=b.len();}}
 fn form(q:&[QubitId],mask:u64)->Lin{let mut v=Lin::k(mask&1!=0);for i in 1..q.len(){if mask>>i&1!=0{v=v.x(&l(q[i]));}}v}
 fn offsets(c:&mut Builder,q:&[QubitId],held:&[QubitId]){for(i,&mask)in F1_OFFSETS.iter().enumerate(){lin_xor_into(c,&form(q,mask),held[i]);}}
 fn basis(c:&mut Builder,q:&[QubitId],held:&[QubitId],inverse:bool){if inverse{offsets(c,q,held);for &(a,b)in F1_CX.iter().rev(){c.cx(held[a],held[b]);}}else{for &(a,b)in F1_CX{c.cx(held[a],held[b]);}offsets(c,q,held);}}
 fn phase(c:&mut Builder,q:&[QubitId],terms:&[(usize,usize)]){for &(a,b)in terms{match(a,b){(0,0)=>{c.cz(q[1],q[1]);c.x(q[1]);c.cz(q[1],q[1]);c.x(q[1]);},(a,0)|(0,a)=>c.cz(q[a],q[a]),(a,b)=>c.cz(q[a],q[b]),}}}
 fn build()->(Vec<Op>,Vec<QubitId>,Vec<QubitId>,crate::circuit::BitId,Vec<usize>,u32){
  let mut c=Builder::new();let acc=c.alloc_qubits(56);let e=c.alloc_qubits(3);let nm=c.alloc_qubits(3);let k1=c.alloc_qubit();let k2=c.alloc_qubit();let guard=c.alloc_bit();let input:Vec<_>=acc[..6].iter().chain(&e).chain(&nm).copied().chain([k1,k2]).collect();c.declare_qubit_register(&input);c.push_condition(guard);
  ON.with(|x|x.set(true));fold_fwd_v2(&mut c,&acc,[e[0],e[1],e[2]],[nm[0],nm[1],nm[2]],k1,k2,1,None,false,0);ON.with(|x|x.set(false));let held=SNAP.with(|x|x.borrow_mut().take()).unwrap();assert_eq!(c.active_qubits(),94);let mut marks=vec![c.op_count()];let q:Vec<_>=std::iter::once(k1).chain(input.iter().copied()).chain(held.iter().copied()).collect();assert_eq!(q.len(),45);
  let(_,peak)=c.r3_peak(|c|{basis(c,&q,&held,false);for &(index,terms)in F1_ERASE{let bit=c.alloc_bit();let target=held[index];c.hmr(target,bit);c.release_clean(target);c.push_condition(bit);if let Some(terms)=terms{phase(c,&q,terms);}else{assert_eq!(index,F1_C3);let aux=maj_wire(c,&l(input[1]),&l(input[7]),&l(held[F1_C1]));lin_cz(c,&Lin::of(&[input[2],aux]),&Lin::of(&[input[8],aux]));c.cz(aux,aux);maj_wire_erase(c,aux,&l(input[1]),&l(input[7]),&l(held[F1_C1]));}c.pop_condition();c.free_bit(bit);}assert_eq!(c.active_qubits(),84);marks.push(c.op_count());
   for &(index,linear,products)in F1_REBUILD{let target=held[index];assert!(c.n2_take(target));if index==F1_C3{let aux=maj_wire(c,&l(input[1]),&l(input[7]),&l(held[F1_C1]));lin_and_into(c,target,&Lin::of(&[input[2],aux]),&Lin::of(&[input[8],aux]));c.cx(aux,target);maj_wire_erase(c,aux,&l(input[1]),&l(input[7]),&l(held[F1_C1]));}else{for &(a,b)in products{lin_and_into(c,target,&form(&q,a),&form(&q,b));}lin_xor_into(c,&form(&q,linear),target);}}
   assert_eq!(c.active_qubits(),94);basis(c,&q,&held,true);
  });assert_eq!(peak,94);c.pop_condition();(c.take_ops(),input,held,guard,marks,peak)
 }
 fn run(guard:u64,probe:Option<usize>){let(ops,input,held,bit,marks,_)=build();let(nq,nb,_,_)=analyze_ops(ops.iter());let nd=ops.iter().filter(|o|matches!(o.kind,OperationType::R|OperationType::Hmr)).count();let expected:Vec<u64>=include_str!("fin1_expected.dat").split_whitespace().map(|x|x.parse().unwrap()).collect();assert_eq!(expected.len(),30*256);let batches:Vec<_>=if probe.is_some(){vec![73]}else{(0..256).collect()};
  for batch in batches{let mut bytes=vec![0u8;nd*8];let mut h=Shake256::default();h.update(b"fin1-helper-native-measurements-v1");h.update(&(batch as u64).to_le_bytes());h.finalize_xof().read(&mut bytes);if let Some(p)=probe{for i in 0..nd{bytes[i*8..i*8+8].copy_from_slice(&(if i==p||p==nd{u64::MAX}else{0u64}).to_le_bytes());}}let prefix_bytes=bytes.clone();let mut rng=Words{bytes,pos:0};let mut s=Simulator::new(nq as usize,nb as usize,&mut rng);for lane in 0..64{let v=batch*64+lane;for(i,&q)in input.iter().enumerate(){if v>>i&1!=0{s.qubits[q.0 as usize]|=1u64<<lane;}}}let initial=s.qubits.clone();s.bits[bit.0 as usize]=guard;s.apply_iter(ops.iter());assert_eq!(s.phase,0,"phase batch{batch} probe{probe:?}");for &q in &input{assert_eq!(s.qubits[q.0 as usize],initial[q.0 as usize]);}for(i,&q)in held.iter().enumerate(){assert_eq!(s.qubits[q.0 as usize],expected[i*256+batch]&guard,"prefix30 helper{i} batch{batch}");}drop(s);assert_eq!(rng.pos,nd*8);
   let mut prefix_rng=Words{bytes:prefix_bytes,pos:0};let mut prefix=Simulator::new(nq as usize,nb as usize,&mut prefix_rng);prefix.qubits.copy_from_slice(&initial);prefix.bits[bit.0 as usize]=guard;prefix.apply_iter(ops[..marks[1]].iter());assert_eq!(prefix.phase,0,"compressed phase batch{batch}");
   let compressed:Vec<u64>=include_str!("fin1_compressed.dat").split_whitespace().map(|x|x.parse().unwrap()).collect();for(i,&q)in held.iter().enumerate(){assert_eq!(prefix.qubits[q.0 as usize],if i<20{compressed[i*256+batch]&guard}else{0},"compressed helper{i} batch{batch}");}for &q in &input{assert_eq!(prefix.qubits[q.0 as usize],initial[q.0 as usize]);}

  }
 }
 #[test]fn prefix_thirty_to_twenty_storage_exact_all_small_inputs_and_conditional_missing_carry_phase(){std::env::set_var("PEBBLE_HARD_CAP","1234");for g in[0,0xA55A_DD33_FF00_1701,u64::MAX]{run(g,None);}let(ops,..)=build();let nd=ops.iter().filter(|o|matches!(o.kind,OperationType::R|OperationType::Hmr)).count();for p in 0..=nd{run(0xA55A_DD33_FF00_1701,Some(p));}}
}
